'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const sticks = input.slice(1).sort((a, b) => a - b);

let count = 0;

for (let k = n - 1; k >= 2; k--) {
  let i = 0;
  let j = k - 1;

  while (i < j) {
    if (sticks[i] + sticks[j] > sticks[k]) {
      count += j - i;
      j--;
    } else {
      i++;
    }
  }
}

console.log(count);
